#!/usr/bin/env python3
"""Port the CLAD (ls-clad) agent toolkit to GitHub Copilot's customization layout.

Fetches https://github.com/lens-studio-devs/ls-extensions (or uses --source) and writes:
  .github/skills/<skill>/            <- plugins/ls-clad/skills/<skill>/
  .github/agents/<name>.agent.md     <- plugins/ls-clad/agents/<name>.md (Copilot frontmatter)
  .github/clad/agent-references/     <- plugins/ls-clad/agents/references/
  .github/clad/LICENSE, manifest.json

Plugin-relative paths (ls-clad/skills/..., ls-clad/agents/...) are rewritten to the
.github locations, and a GitHub Copilot entry is added to the cross-runtime rules in
lens-studio-field-notes and lens-studio-router. The liveness hook in .github/hooks/ is
hand-written for Copilot and is not touched by this script.

Usage:  python3 .github/clad/sync-clad.py [--ref main] [--source /path/to/ls-extensions]
"""
import argparse
import json
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

REPO_URL = "https://github.com/lens-studio-devs/ls-extensions.git"
ROOT = Path(__file__).resolve().parents[2]
GH = ROOT / ".github"
CLAD = GH / "clad"
MANIFEST = CLAD / "manifest.json"
GENERATED_MARK = "<!-- Generated by .github/clad/sync-clad.py from ls-clad; re-run the script instead of editing. -->"

TOOL_ALIASES = {
    "Read": "read",
    "Grep": "search",
    "Glob": "search",
    "Edit": "edit",
    "Write": "edit",
    "MultiEdit": "edit",
    "NotebookEdit": "edit",
    "Bash": "execute",
    "WebFetch": "web",
    "WebSearch": "web",
    "TaskCreate": "todo",
    "TaskUpdate": "todo",
    "TaskList": "todo",
    "TodoWrite": "todo",
    "Agent": "agent",
    "Task": "agent",
}
# Claude-only tools with no Copilot tools: entry. Skills are read from .github/skills,
# deferred tool loading is automatic, and subagents return questions to the parent.
DROPPED_TOOLS = {"Skill", "ToolSearch", "AskUserQuestion"}

COPILOT_NAMING_BULLET = """   - **GitHub Copilot (VS Code chat, Copilot app, Copilot CLI/SDK):** server `lens-studio` (Lens Studio writes it to `.vscode/mcp.json` / `.mcp.json` when the project is open). Tools surface as `lens-studio-<Tool>` in the Copilot harness (a `mcp_lens-studio_<Tool>`-style id in VS Code Local chat); in `.agent.md` `tools:` frontmatter use `lens-studio/<Tool>` or `lens-studio/*`. They may be **deferred**: if a tool is not in your list, load it with your tool-search facility (query the bare tool name); if only an `mcp_route_lens-studio_*` entry exists, call it once to connect the server, then search again. A connection/transport error means Lens Studio is not running with this project open - stop and tell the user; do not work around it."""

COPILOT_ORCHESTRATION = """- **GitHub Copilot mapping.** The ls-clad toolkit is installed in this repo for Copilot: skills at `.github/skills/<skill>/SKILL.md`, agents at `.github/agents/<name>.agent.md`, agent references at `.github/clad/agent-references/`. Drop the `ls-clad:` prefix everywhere (`ls-clad:scene-construction` = skill `scene-construction`; `ls-clad:specs-experience-builder` = custom agent `specs-experience-builder`). **Spawn:** use your subagent tool (`task` / `runSubagent`) with the bare custom-agent name; if custom agents are not offered, spawn a general-purpose subagent whose prompt is the agent file's body plus the handoff, or run that file inline. **Continue:** `write_agent` to an idle background agent where available, else spawn fresh. **Skill:** the `skill` tool or `/<skill>` with the bare name, else read the SKILL.md. **Ask:** `ask_user` (Copilot CLI/SDK) or the ask-questions tool (VS Code) - both blocking; a subagent without one returns the question to its parent. **Progress:** the todo facility (`manage_todo_list` in VS Code, the `sql` `todos` table in Copilot CLI/SDK)."""

ROUTER_COPILOT_BULLET = """- **GitHub Copilot.** Ask with `ask_user` / the ask-questions tool (blocking). Spawn `specs-experience-builder` as a custom agent from `.github/agents/specs-experience-builder.agent.md` by its bare name (no `ls-clad:` prefix) via the subagent tool; if custom agents are not offered, run that file inline. Lens Studio MCP tools may be deferred - load them via tool search before the Gate (see `lens-studio-field-notes` Hard Rule 2 and its GitHub Copilot mapping)."""


def run(cmd, **kw):
    return subprocess.run(cmd, check=True, text=True, capture_output=True, **kw).stdout.strip()


def rewrite_paths(text: str) -> str:
    text = text.replace("ls-clad/agents/references/", ".github/clad/agent-references/")
    text = re.sub(r"ls-clad/agents/([A-Za-z0-9_<>*-]+)\.md", r".github/agents/\1.agent.md", text)
    text = text.replace("ls-clad/agents/", ".github/agents/")
    text = text.replace("ls-clad/skills/", ".github/skills/")
    text = text.replace(".claude/skills/migration/specs-27-migration/SKILL.md", ".github/skills/specs-27-migration/SKILL.md")
    return text


def insert_after(text: str, anchor_regex: str, addition: str, label: str) -> str:
    m = re.search(anchor_regex, text, re.M)
    if not m:
        sys.exit(f"sync-clad: anchor for {label} not found; upstream layout changed, update sync-clad.py")
    return text[: m.end()] + "\n" + addition + text[m.end():]


def patch_field_notes(path: Path):
    t = path.read_text()
    t = insert_after(t, r"^   - \*\*Cursor:\*\*.*$", COPILOT_NAMING_BULLET, "field-notes Hard Rule 2")
    t = insert_after(t, r"^- \*\*Show progress\.\*\*.*$", COPILOT_ORCHESTRATION, "field-notes orchestration")
    path.write_text(t)


def patch_router(path: Path):
    t = path.read_text()
    t = insert_after(t, r"^- \*\*Spawning subagents\*\*.*$", "\n" + ROUTER_COPILOT_BULLET, "router cross-runtime")
    path.write_text(t)


def split_frontmatter(text: str):
    m = re.match(r"---\n(.*?)\n---\n?", text, re.S)
    if not m:
        sys.exit("sync-clad: agent file without frontmatter")
    return m.group(1), text[m.end():]


def parse_frontmatter(fm: str):
    """Minimal parser for the ls-clad agent frontmatter shapes (scalar, folded, list, inline list)."""
    data, key, lines = {}, None, fm.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        m = re.match(r"^([A-Za-z][\w-]*):\s*(.*)$", line)
        if m:
            key, val = m.group(1), m.group(2)
            if val in (">-", ">", "|", "|-"):
                block = []
                i += 1
                while i < len(lines) and (lines[i].startswith(" ") or not lines[i].strip()):
                    block.append(lines[i].strip())
                    i += 1
                data[key] = " ".join(b for b in block if b)
                continue
            if val == "":
                items = []
                i += 1
                while i < len(lines) and re.match(r"^\s+-\s+", lines[i]):
                    items.append(re.sub(r"^\s+-\s+", "", lines[i]).strip())
                    i += 1
                data[key] = items
                continue
            if val.startswith('"') and val.endswith('"'):
                val = json.loads(val)
            data[key] = val
        i += 1
    return data


def map_tools(tools):
    if isinstance(tools, str):
        tools = [t.strip() for t in tools.split(",") if t.strip()]
    out = []
    for t in tools:
        if t in DROPPED_TOOLS:
            continue
        m = re.match(r"^mcp__([\w-]+)__(.+)$", t)
        mapped = f"{m.group(1)}/{m.group(2)}" if m else TOOL_ALIASES.get(t)
        if mapped is None:
            sys.exit(f"sync-clad: no Copilot mapping for agent tool '{t}'")
        if mapped not in out:
            out.append(mapped)
    return out


def yaml_str(s: str) -> str:
    return json.dumps(s, ensure_ascii=False)


def convert_agent(src: Path, dst: Path, local_refs: set):
    fm, body = split_frontmatter(src.read_text())
    data = parse_frontmatter(fm)
    name = data.get("name", src.stem)
    lines = ["---", f"name: {name}", f"description: {yaml_str(data['description'])}"]
    if "tools" in data:
        lines.append("tools: [" + ", ".join(yaml_str(t) for t in map_tools(data["tools"])) + "]")
    lines.append("---")
    preload = ""
    skills = data.get("skills")
    if skills:
        skills = [skills] if isinstance(skills, str) else skills
        refs = ", ".join(f"`.github/skills/{s}/SKILL.md`" for s in skills)
        preload = f"\n> **Preloaded skills (GitHub Copilot):** before doing anything else, read {refs} in full.\n"
    body = rewrite_paths(body)
    # Only agent-local references move; bare references/ paths into skills stay as written upstream.
    body = re.sub(
        r"(?<![\w./-])references/([\w.-]+\.md)",
        lambda m: f".github/clad/agent-references/{m.group(1)}" if m.group(1) in local_refs else m.group(0),
        body,
    )
    dst.write_text("\n".join(lines) + "\n" + GENERATED_MARK + "\n" + preload + body)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--ref", default="main", help="ls-extensions git ref to port (default: main)")
    ap.add_argument("--source", help="existing local clone of ls-extensions (skips git clone)")
    args = ap.parse_args()

    tmp = None
    if args.source:
        repo = Path(args.source).resolve()
    else:
        tmp = tempfile.mkdtemp(prefix="ls-extensions-")
        repo = Path(tmp)
        run(["git", "clone", "--quiet", "--depth", "1", "--branch", args.ref, REPO_URL, str(repo)])
    try:
        commit = run(["git", "-C", str(repo), "rev-parse", "HEAD"])
        plugin = repo / "plugins" / "ls-clad"
        if not plugin.is_dir():
            sys.exit(f"sync-clad: {plugin} not found")

        old = json.loads(MANIFEST.read_text()) if MANIFEST.exists() else {"skills": [], "agents": []}
        for s in old.get("skills", []):
            shutil.rmtree(GH / "skills" / s, ignore_errors=True)
        for a in old.get("agents", []):
            (GH / "agents" / f"{a}.agent.md").unlink(missing_ok=True)
        shutil.rmtree(CLAD / "agent-references", ignore_errors=True)

        skills_dst = GH / "skills"
        skills_dst.mkdir(parents=True, exist_ok=True)
        skills = sorted(p.name for p in (plugin / "skills").iterdir() if (p / "SKILL.md").is_file())
        for s in skills:
            dst = skills_dst / s
            if dst.exists() and s not in old.get("skills", []):
                sys.exit(f"sync-clad: .github/skills/{s} exists and is not CLAD-managed; refusing to overwrite")
            shutil.copytree(plugin / "skills" / s, dst)
            for f in dst.rglob("*"):
                if f.is_file() and f.suffix in {".md", ".mdx", ".py", ".js", ".ts", ".sh", ".txt", ".json"}:
                    try:
                        t = f.read_text()
                    except UnicodeDecodeError:
                        continue
                    nt = rewrite_paths(t)
                    if nt != t:
                        f.write_text(nt)
        patch_field_notes(skills_dst / "lens-studio-field-notes" / "SKILL.md")
        patch_router(skills_dst / "lens-studio-router" / "SKILL.md")

        agents_dst = GH / "agents"
        agents_dst.mkdir(parents=True, exist_ok=True)
        refs_src = plugin / "agents" / "references"
        local_refs = {p.name for p in refs_src.glob("*.md")} if refs_src.is_dir() else set()
        agents = sorted(p.stem for p in (plugin / "agents").glob("*.md"))
        for a in agents:
            dst = agents_dst / f"{a}.agent.md"
            if dst.exists() and a not in old.get("agents", []):
                sys.exit(f"sync-clad: .github/agents/{a}.agent.md exists and is not CLAD-managed; refusing to overwrite")
            convert_agent(plugin / "agents" / f"{a}.md", dst, local_refs)

        if refs_src.is_dir():
            shutil.copytree(refs_src, CLAD / "agent-references")
            for f in (CLAD / "agent-references").rglob("*.md"):
                f.write_text(rewrite_paths(f.read_text()))

        shutil.copy2(repo / "LICENSE", CLAD / "LICENSE")
        MANIFEST.write_text(json.dumps({
            "upstream": REPO_URL,
            "commit": commit,
            "skills": skills,
            "agents": agents,
        }, indent=2) + "\n")
        print(f"sync-clad: ported ls-clad@{commit[:7]} -> {len(skills)} skills, {len(agents)} agents")
    finally:
        if tmp:
            shutil.rmtree(tmp, ignore_errors=True)


if __name__ == "__main__":
    main()
